'use strict';
const { listItems } = require('./items');
function getItems(items, query = {}) {
  const limit = query.limit === undefined ? 20 : Number(query.limit);
  if (!Number.isInteger(limit) || limit < 1 || limit > 100) throw new RangeError('invalid limit');
  return listItems(items, { limit, includeArchived: query.includeArchived === 'true' });
}
module.exports = { getItems };

